#!/usr/bin/env python3
"""Z1190: are the denominator triples of canonical (large-height) solutions generated by short
recurrences?  Test: canonical solution for n = 24k+1 (k = 1..K): least x, then least y.
Then search for a linear recurrence with polynomial coefficients (holonomic guess):
   sum_{i=0..o} sum_{j=0..d} c_{ij} k^j a_{k+i} = 0,   o <= 5, d <= 3,
for each of a_k in {x_k, y_k, z_k} (exact rational nullspace, verified on the held-out tail).
Also: constant-coefficient recurrences of order <= 3 (d = 0) are a special case.
Height proxy: log10 of max denominator.
"""
import sys, json, math
import sympy as sp

def factor(n):
    f = {}; d = 2
    while d * d <= n:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1; n //= d
        d += 1
    if n > 1: f[n] = f.get(n, 0) + 1
    return f

def divisors_sq(M):
    ds = [1]
    for q, a in factor(M).items():
        ds = [d * q ** i for d in ds for i in range(2 * a + 1)]
    return ds

def canonical(n):
    x0 = -(-n // 4)
    for x in range(x0 + 1, 3 * n // 4 + 2):   # x <= y <= z forces x <= 3n/4
        r = 4 * x - n
        if r <= 0:
            continue
        M = n * x
        best = None
        for e in sorted(divisors_sq(M)):
            if (e + M) % r: continue
            f = M * M // e
            if (f + M) % r: continue
            y = (e + M) // r; z = (f + M) // r
            if x <= y <= z:
                if best is None or (y, z) < best:
                    best = (y, z)
        if best is not None:
            return x, best[0], best[1]
    return None

def find_recurrence(seq, order, deg, start=1):
    """seq: list of ints indexed from k=start. Solve for c_{ij}; return basis or None."""
    K = len(seq)
    rows = []
    unknowns = (order + 1) * (deg + 1)
    for idx in range(K - order):
        k = start + idx
        row = []
        for i in range(order + 1):
            for j in range(deg + 1):
                row.append(sp.Integer(k) ** j * sp.Integer(seq[idx + i]))
        rows.append(row)
    if len(rows) < unknowns + 8:
        return None
    Mx = sp.Matrix(rows)
    ns = Mx.nullspace()
    return ns, unknowns, len(rows)

def main(K=60):
    data = []
    for k in range(1, K + 1):
        n = 24 * k + 1
        c = canonical(n)
        data.append((k, n, c))
    res = {}
    for name, idx in (("x", 0), ("y", 1), ("z", 2)):
        seq = [c[idx] for _, _, c in data]
        found = None
        for order in range(1, 6):
            for deg in range(0, 4):
                out = find_recurrence(seq, order, deg)
                if out is None:
                    continue
                ns, unk, neq = out
                if ns:
                    found = (order, deg, neq, unk, len(ns))
                    break
            if found:
                break
        res[name] = found
    heights = [math.log10(max(c)) for _, _, c in data]
    return data, res, heights

if __name__ == "__main__":
    K = int(sys.argv[1]) if len(sys.argv) > 1 else 60
    data, res, heights = main(K)
    print("K =", K, " n = 24k+1 from k=1..K; canonical solutions found:", sum(1 for _, _, c in data if c))
    print("sample:", [(n, c) for _, n, c in data[:4]])
    print("max log10 denominator:", round(max(heights), 2), " median:", round(sorted(heights)[len(heights)//2], 2))
    print("recurrence found (order, deg, #eqs, #unknowns, nullity) per sequence:", res)
    json.dump({"K": K, "data": [(k, n, c) for k, n, c in data], "recurrence": res},
              open(f"data/z52b/pass2/NC0/sub/Z1190_rec_{K}.json", "w"))
